// @effect-diagnostics nodeBuiltinImport:off -- Content-addressed browser assets generated by Vite.
import { createHash } from "node:crypto";
type AssetEmitter = { emitFile(asset: { type: "asset"; fileName: string; source: string }): string };
import { visitStrings, type Parse } from "./contexts.ts";

export function englishAsset(context: AssetEmitter, name: string, source: string) {
  const hash = createHash("sha256").update(source).digest("hex").slice(0, 16);
  const fileName = "assets/" + name + "-" + hash + ".js";
  context.emitFile({ type: "asset", fileName, source });
  return "/" + fileName;
}

// Chronos-owned copy is already Russian in the source. Only replace authored literals,
// leaving interpolation values, property keys, routing strings and user data intact.
export function englishLiterals(code: string, parse: Parse, dictionary: Record<string, string>) {
  if (!/[а-яё]/iu.test(code) && !/\\u0[45]/iu.test(code)) return code;
  const chunks: string[] = [];
  let offset = 0;
  visitStrings(code, parse, (site) => {
    if (site.slots.length) return;
    const original = site.parts[0]!;
    const key = original.trim().replace(/\s+/gu, " ");
    if (!Object.hasOwn(dictionary, key)) return;
    const value = original.replace(original.trim(), () => dictionary[key]!);
    chunks.push(code.slice(offset, site.start), JSON.stringify(value));
    offset = site.end;
    return true;
  });
  return chunks.length ? chunks.join("") + code.slice(offset) : code;
}

export function localizeEntryHtml(html: string, englishSetup: string) {
  const links: string[] = [];
  const withoutPreloads = html.replace(/<link\b[^>]*\brel="modulepreload"[^>]*>/gu, tag => {
    const href = /\bhref="([^"]+)"/u.exec(tag)?.[1];
    if (!href) return tag;
    links.push(href);
    return "";
  });
  const entryTag = /<script\b(?=[^>]*\btype="module")[^>]*\bsrc="([^"]+)"[^>]*><\/script>/u;
  if (!entryTag.test(withoutPreloads)) throw new Error("Missing Chronos HTML module entry");
  return withoutPreloads.replace(entryTag, (_tag, entry: string) => {
    // The desktop settings read is shared with hydration. An import map has to be in
    // place before even the first modulepreload (which can resolve transitive imports).
    return '<script type="module">\n' +
      'let saved;\n' +
      'try { if (window.desktopBridge) {\n' +
      '  window.__chronosInitialSettings = window.desktopBridge.getClientSettings();\n' +
      '  saved = await window.__chronosInitialSettings;\n' +
      '} else saved = JSON.parse(localStorage.getItem("t3code:client-settings:v1")); } catch {}\n' +
      'const language = saved?.language || "ru";\n' +
      'window.__chronosInitialLanguage = language;\n' +
      'const russian = (language === "system" ? navigator.language : language).split("-")[0] === "ru";\n' +
      'window.__chronosShellLanguage = russian ? "ru" : "en";\n' +
      'const imports = russian ? {} : (await import(' + JSON.stringify(englishSetup) + ')).imports;\n' +
      'for (const href of ' + JSON.stringify(links) + ') {\n' +
      '  const link = document.createElement("link"); link.rel = "modulepreload";\n' +
      '  link.crossOrigin = ""; link.href = imports[href] || href; document.head.append(link);\n' +
      '}\nawait import(' + JSON.stringify(entry) + ');\n</script>';
  });
}
